  const ring=new THREE.RingGeometry(.94,1,64),disc=new THREE.CircleGeometry(1,48),cross=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-1,0,0),new THREE.Vector3(1,0,0),new THREE.Vector3(0,-1,0),new THREE.Vector3(0,1,0)]);
  for(let i=0;i<this.config.count;i++){const root=new THREE.Group(),material=new THREE.MeshBasicMaterial({color:'#ff6845',transparent:true,opacity:.85,side:THREE.DoubleSide,depthWrite:false}),outer=new THREE.Mesh(ring,material),countdown=new THREE.Mesh(ring,material.clone()),fill=new THREE.Mesh(disc,material.clone()),reticle=new THREE.LineSegments(cross,new THREE.LineBasicMaterial({color:'#ffc897',transparent:true,opacity:.8,depthWrite:false}));fill.material.opacity=.13;root.rotation.x=-Math.PI/2;root.add(fill,outer,countdown,reticle);root.visible=false;this.group.add(root);this.markers.push({root,outer,countdown,fill,reticle,material});}
