 reset(){this.time=0;this.launched=this.impacts=this.interceptions=0;this.pending=[];this.shells=[];this.effects.reset();for(const marker of this.markers)marker.root.visible=false;for(const mesh of[this.core,this.glow,this.trails])mesh.count=0;}
